-- ============================================================================
--  Catálogo ampliado a 50 especies + fichas en la base.
--  GENERADO por scripts/generar-catalogo.mjs — no editar a mano.
--  Idempotente: las especies se insertan o se actualizan por nombre científico.
-- ============================================================================

set search_path = mariposas, public, extensions;

alter table especies add column if not exists slug           text;
alter table especies add column if not exists envergadura    text;
alter table especies add column if not exists vuelo          text;
alter table especies add column if not exists disponibilidad text;
alter table especies add column if not exists destacada      boolean not null default false;

-- Slug para la página de cada especie: el nombre científico en kebab-case.
update especies set slug = lower(regexp_replace(trim(nombre_cientifico), '\s+', '-', 'g')) where slug is null;
create unique index if not exists especies_slug_idx on especies (slug);

-- El catálogo público lee estas columnas (el precio sigue sin ser público).
grant select (slug, envergadura, vuelo, disponibilidad, destacada) on especies to anon, authenticated;

-- Fichas de las especies originales (antes en lib/fichas.ts)
update especies set envergadura = '95–120 mm', vuelo = 'Alto y errático, en claros', disponibilidad = 'Todo el año', destacada = true, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"High and erratic, in clearings","disponibilidad":"Year-round"},"it":{"vuelo":"Alto e irregolare, nelle radure","disponibilidad":"Tutto l''anno"},"fr":{"vuelo":"Haut et erratique, dans les clairières","disponibilidad":"Toute l''année"},"zh":{"vuelo":"高飞且飞行轨迹不规则，常见于林间空地","disponibilidad":"全年供应"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Morpho peleides';
update especies set envergadura = '120–150 mm', vuelo = 'Crepuscular, bajo', disponibilidad = 'Todo el año', destacada = true, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"Low, at dusk","disponibilidad":"Year-round"},"it":{"vuelo":"Crepuscolare, basso","disponibilidad":"Tutto l''anno"},"fr":{"vuelo":"Crépusculaire, bas","disponibilidad":"Toute l''année"},"zh":{"vuelo":"晨昏活动，低飞","disponibilidad":"全年供应"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Caligo memnon';
update especies set envergadura = '90–100 mm', vuelo = 'Planeado, sostenido', disponibilidad = 'Todo el año', destacada = false, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"Gliding, sustained","disponibilidad":"Year-round"},"it":{"vuelo":"Planato, prolungato","disponibilidad":"Tutto l''anno"},"fr":{"vuelo":"Plané, soutenu","disponibilidad":"Toute l''année"},"zh":{"vuelo":"滑翔，持久飞行","disponibilidad":"全年供应"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Danaus plexippus';
update especies set envergadura = '55–61 mm', vuelo = 'Bajo, entre sotobosque', disponibilidad = 'Todo el año', destacada = true, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"Low, through the understory","disponibilidad":"Year-round"},"it":{"vuelo":"Basso, nel sottobosco","disponibilidad":"Tutto l''anno"},"fr":{"vuelo":"Bas, dans le sous-bois","disponibilidad":"Toute l''année"},"zh":{"vuelo":"低飞，穿行于林下植被间","disponibilidad":"全年供应"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Greta oto';
update especies set envergadura = '72–100 mm', vuelo = 'Lento y flotante', disponibilidad = 'Todo el año', destacada = false, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"Slow and floating","disponibilidad":"Year-round"},"it":{"vuelo":"Lento e fluttuante","disponibilidad":"Tutto l''anno"},"fr":{"vuelo":"Lent et flottant","disponibilidad":"Toute l''année"},"zh":{"vuelo":"缓慢，似漂浮","disponibilidad":"全年供应"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Heliconius charithonia';
update especies set envergadura = '100–130 mm', vuelo = 'Rápido, con aleteo continuo', disponibilidad = 'Todo el año', destacada = true, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"Fast, with constant wingbeats","disponibilidad":"Year-round"},"it":{"vuelo":"Rapido, con battito d''ali continuo","disponibilidad":"Tutto l''anno"},"fr":{"vuelo":"Rapide, avec des battements d''ailes continus","disponibilidad":"Toute l''année"},"zh":{"vuelo":"快速，持续振翅","disponibilidad":"全年供应"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Papilio thoas';
update especies set envergadura = '60–80 mm', vuelo = 'Medio, posa con frecuencia', disponibilidad = 'Todo el año', destacada = false, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"Moderate, lands often","disponibilidad":"Year-round"},"it":{"vuelo":"Medio, si posa spesso","disponibilidad":"Tutto l''anno"},"fr":{"vuelo":"Moyen, se pose fréquemment","disponibilidad":"Toute l''année"},"zh":{"vuelo":"中等高度，经常停歇","disponibilidad":"全年供应"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Siproeta stelenes';
update especies set envergadura = '35–40 mm', vuelo = 'Rápido y bajo', disponibilidad = 'Marzo a octubre', destacada = false, traducciones = coalesce(traducciones, '{}'::jsonb) || (select jsonb_object_agg(k, coalesce(traducciones->k, '{}'::jsonb) || v) from jsonb_each('{"en":{"vuelo":"Fast and low","disponibilidad":"March to October"},"it":{"vuelo":"Rapido e basso","disponibilidad":"Da marzo a ottobre"},"fr":{"vuelo":"Rapide et bas","disponibilidad":"De mars à octobre"},"zh":{"vuelo":"快速且低飞","disponibilidad":"3 月至 10 月"}}'::jsonb) as e(k, v)) where nombre_cientifico = 'Diaethria astala';

-- 42 especies nuevas (precio en 0: se carga desde /admin/especies)
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Heliconia azul y blanca', 'Heliconius cydno', 'Nymphalidae', 'México a Sudamérica noroccidental', 0, 'Alas negras con reflejos azul metálico y una amplia banda blanca en las alas anteriores. Vuela con calma entre las flores, se alimenta de néctar y polen, y los adultos pueden vivir varias semanas. Su contraste de colores y su longevidad la convierten en una especie muy vistosa y rentable para cualquier mariposario.', 'heliconius-cydno', '70–85 mm', 'Lento y planeado', 'Bajo pedido', true, '{"en":{"nombre_comun":"Blue-and-white Longwing","region":"Mexico to northwestern South America","descripcion":"Black wings washed with metallic blue and crossed by a broad white forewing band. It drifts calmly from flower to flower, feeding on both nectar and pollen, and adults can live for several weeks. Striking contrast and a long display life make it a dependable showpiece for any butterfly house.","vuelo":"Slow and gliding","disponibilidad":"On request"},"it":{"nombre_comun":"Heliconius blu e bianco","region":"Dal Messico al Sudamerica nord-occidentale","descripcion":"Ali nere con riflessi blu metallico e un''ampia fascia bianca sulle ali anteriori. Vola con calma tra i fiori, si nutre di nettare e polline e gli adulti possono vivere diverse settimane. Il forte contrasto cromatico e la lunga durata in esposizione la rendono una specie affidabile e di grande effetto.","vuelo":"Lento e planato","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Héliconius bleu et blanc","region":"Du Mexique au nord-ouest de l''Amérique du Sud","descripcion":"Ailes noires aux reflets bleu métallique, traversées d''une large bande blanche sur l''aile antérieure. Il passe calmement de fleur en fleur, se nourrit de nectar et de pollen, et les adultes vivent plusieurs semaines. Son contraste saisissant et sa longévité en font une valeur sûre pour toute serre à papillons.","vuelo":"Lent et plané","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"蓝白袖蝶","region":"墨西哥至南美洲西北部","descripcion":"翅膀黑色，带金属蓝光泽，前翅有一条宽阔的白色横带。飞行从容，在花间穿梭，同时取食花蜜和花粉，成虫可存活数周。色彩对比鲜明、展示寿命长，是蝴蝶馆中稳定而醒目的展示物种。","vuelo":"缓慢滑翔","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Heliconia doris', 'Heliconius doris', 'Nymphalidae', 'México a la Amazonía', 0, 'Alas negras con manchas amarillas en las anteriores y rayos en las posteriores que pueden ser rojos, azules o verdes según el individuo. Planea despacio y visita flores con constancia, con adultos de vida larga. Su variedad de formas de color permite mostrar el polimorfismo en vivo y despierta la curiosidad del público.', 'heliconius-doris', '65–85 mm', 'Lento, a media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Doris Longwing","region":"Mexico to the Amazon Basin","descripcion":"Black wings with yellow forewing spots and hindwing rays that may be red, blue or green depending on the individual. It glides unhurriedly and visits flowers steadily, and adults are long-lived. Its range of colour forms lets visitors see polymorphism in action, making it an engaging educational species.","vuelo":"Slow, mid-level","disponibilidad":"On request"},"it":{"nombre_comun":"Heliconius doris","region":"Dal Messico all''Amazzonia","descripcion":"Ali nere con macchie gialle sulle anteriori e raggi sulle posteriori che possono essere rossi, blu o verdi a seconda dell''individuo. Plana senza fretta e visita i fiori con costanza; gli adulti sono longevi. Le sue diverse forme cromatiche mostrano dal vivo il polimorfismo, rendendola una specie didattica molto apprezzata.","vuelo":"Lento, a media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Héliconius doris","region":"Du Mexique à l''Amazonie","descripcion":"Ailes noires ornées de taches jaunes à l''avant et de rayons à l''arrière, rouges, bleus ou verts selon l''individu. Il plane sans hâte, butine régulièrement et les adultes vivent longtemps. Ses différentes formes colorées illustrent le polymorphisme en direct, ce qui en fait une espèce pédagogique très appréciée.","vuelo":"Lent, à mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"多丽袖蝶","region":"墨西哥至亚马孙流域","descripcion":"翅膀黑色，前翅有黄色斑，后翅的放射状条纹因个体不同而呈红色、蓝色或绿色。飞行舒缓，经常访花，成虫寿命较长。多种色型可让游客直观了解多态现象，是很有教育意义的展示物种。","vuelo":"缓慢，中等高度","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Cartero pequeño', 'Heliconius erato', 'Nymphalidae', 'Sur de EE. UU. a Sudamérica', 0, 'Alas negras con una franja roja en las anteriores y, en las formas centroamericanas, una línea amarilla en las posteriores. Revolotea con suavidad entre las flores, recolecta polen y duerme en grupo sobre ramas o bejucos. Es resistente, longeva y muy activa durante el día, ideal para mantener un mariposario siempre animado.', 'heliconius-erato', '55–75 mm', 'Lento y ondulante', 'Bajo pedido', true, '{"en":{"nombre_comun":"Small Postman","region":"Southern USA to South America","descripcion":"Black wings with a red forewing band and, in Central American forms, a thin yellow hindwing line. It flutters gently among flowers, gathers pollen and roosts communally on twigs and vines at night. Hardy, long-lived and active all day, it keeps a flight house lively from morning to closing time.","vuelo":"Slow and fluttering","disponibilidad":"On request"},"it":{"nombre_comun":"Piccolo postino","region":"Dal sud degli Stati Uniti al Sudamerica","descripcion":"Ali nere con una fascia rossa sulle anteriori e, nelle forme centroamericane, una sottile linea gialla sulle posteriori. Svolazza dolcemente tra i fiori, raccoglie polline e di notte riposa in gruppo su rametti e liane. Robusta, longeva e attiva tutto il giorno, mantiene vivace qualsiasi serra delle farfalle.","vuelo":"Lento e svolazzante","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Petit facteur","region":"Du sud des États-Unis à l''Amérique du Sud","descripcion":"Ailes noires marquées d''une bande rouge à l''avant et, chez les formes d''Amérique centrale, d''un fin trait jaune à l''arrière. Il voltige doucement entre les fleurs, récolte du pollen et dort en groupe sur des rameaux ou des lianes. Robuste, longévif et actif toute la journée, il anime durablement une serre.","vuelo":"Lent et voletant","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"艺神袖蝶","region":"美国南部至南美洲","descripcion":"翅膀黑色，前翅有红色宽带，中美洲类型的后翅还有一条细黄线。在花间轻柔飞舞，会采集花粉，夜间成群栖息在细枝或藤蔓上。体质强健、寿命长、白天活跃，能让蝴蝶馆全天充满生气。","vuelo":"缓慢，轻盈拍翅","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Heliconia tigre', 'Heliconius hecale', 'Nymphalidae', 'México a Perú', 0, 'Diseño atigrado de negro, naranja y amarillo, con manchas claras en la punta de las alas anteriores. Es una de las heliconias más grandes; vuela pausadamente, frecuenta las flores y los adultos viven varias semanas. Su tamaño y colorido cálido la hacen muy fotogénica y una de las favoritas del público.', 'heliconius-hecale', '70–90 mm', 'Lento y planeado', 'Bajo pedido', true, '{"en":{"nombre_comun":"Tiger Longwing","region":"Mexico to Peru","descripcion":"A tiger pattern of black, orange and yellow, with pale spots near the forewing tips. One of the larger longwings, it flies at a leisurely pace, visits flowers often and adults live for several weeks. Its size and warm colours make it highly photogenic and a consistent visitor favourite.","vuelo":"Slow and gliding","disponibilidad":"On request"},"it":{"nombre_comun":"Heliconius tigrato","region":"Dal Messico al Perù","descripcion":"Disegno tigrato nero, arancione e giallo, con macchie chiare verso l''apice delle ali anteriori. È uno degli Heliconius più grandi: vola con calma, visita spesso i fiori e gli adulti vivono diverse settimane. Dimensioni e colori caldi lo rendono molto fotogenico e tra i preferiti dei visitatori.","vuelo":"Lento e planato","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Héliconius tigré","region":"Du Mexique au Pérou","descripcion":"Motif tigré noir, orange et jaune, avec des taches claires vers l''apex des ailes antérieures. C''est l''un des plus grands héliconius : il vole posément, butine souvent et les adultes vivent plusieurs semaines. Sa taille et ses couleurs chaudes le rendent très photogénique et apprécié du public.","vuelo":"Lent et plané","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"虎纹袖蝶","region":"墨西哥至秘鲁","descripcion":"翅面为黑、橙、黄三色组成的虎纹图案，前翅端部有浅色斑点。属于体型较大的袖蝶，飞行悠闲，频繁访花，成虫可存活数周。体型大、色彩温暖，非常上镜，深受游客喜爱。","vuelo":"缓慢滑翔","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Heliconia de Hewitson', 'Heliconius hewitsoni', 'Nymphalidae', 'Costa Rica y Panamá', 0, 'Alas negras cruzadas por bandas blancas bien definidas, un diseño elegante y sobrio. Es una especie de distribución restringida al sur de Centroamérica, de vuelo tranquilo y adultos longevos que visitan flores con regularidad. Su rareza en colecciones vivas la convierte en una pieza destacada para exhibiciones especializadas.', 'heliconius-hewitsoni', '70–85 mm', 'Lento, a media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Hewitson''s Longwing","region":"Costa Rica and Panama","descripcion":"Black wings crossed by crisp white bands give this longwing a clean, elegant look. Restricted to southern Central America, it flies calmly and its long-lived adults visit flowers regularly. Seldom seen in live collections, it is a distinctive highlight for specialised or regional exhibits.","vuelo":"Slow, mid-level","disponibilidad":"On request"},"it":{"nombre_comun":"Heliconius di Hewitson","region":"Costa Rica e Panamá","descripcion":"Ali nere attraversate da nitide fasce bianche, per un aspetto sobrio ed elegante. Diffusa solo nel sud dell''America centrale, vola con calma e gli adulti, longevi, visitano regolarmente i fiori. Raramente presente nelle collezioni vive, è un pezzo di pregio per esposizioni specializzate.","vuelo":"Lento, a media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Héliconius de Hewitson","region":"Costa Rica et Panama","descripcion":"Ailes noires traversées de bandes blanches nettes, pour une allure sobre et élégante. Limité au sud de l''Amérique centrale, il vole calmement et ses adultes longévifs butinent régulièrement. Rarement présenté dans les collections vivantes, il constitue un atout remarquable pour les expositions spécialisées.","vuelo":"Lent, à mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"休氏袖蝶","region":"哥斯达黎加和巴拿马","descripcion":"黑色翅面上横贯清晰的白色条带，外观简洁优雅。仅分布于中美洲南部，飞行平稳，成虫寿命长并经常访花。在活体展示中较为少见，是专题展览中的亮点物种。","vuelo":"缓慢，中等高度","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Cartero', 'Heliconius melpomene', 'Nymphalidae', 'México a Sudamérica', 0, 'Alas negras con una llamativa banda roja en las anteriores, casi idéntica a la de Heliconius erato por mimetismo. Vuela despacio, se alimenta de néctar y polen y sus adultos viven varias semanas. Es un clásico de los mariposarios y un excelente ejemplo para explicar el mimetismo mülleriano.', 'heliconius-melpomene', '60–80 mm', 'Lento y ondulante', 'Bajo pedido', true, '{"en":{"nombre_comun":"Postman","region":"Mexico to South America","descripcion":"Black wings with a bold red forewing band, almost identical to Heliconius erato through mimicry. It flies slowly, feeds on nectar and pollen, and adults live for several weeks. A butterfly-house classic and an ideal species for explaining Müllerian mimicry to visitors.","vuelo":"Slow and fluttering","disponibilidad":"On request"},"it":{"nombre_comun":"Postino","region":"Dal Messico al Sudamerica","descripcion":"Ali nere con una vistosa fascia rossa sulle anteriori, quasi identica a quella di Heliconius erato per mimetismo. Vola lentamente, si nutre di nettare e polline e gli adulti vivono diverse settimane. Un classico delle case delle farfalle, perfetto per spiegare il mimetismo mülleriano.","vuelo":"Lento e svolazzante","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Facteur","region":"Du Mexique à l''Amérique du Sud","descripcion":"Ailes noires barrées d''une bande rouge vif à l''avant, presque identique à celle d''Heliconius erato par mimétisme. Il vole lentement, se nourrit de nectar et de pollen et les adultes vivent plusieurs semaines. Un classique des serres à papillons, idéal pour présenter le mimétisme müllérien.","vuelo":"Lent et voletant","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"红带袖蝶","region":"墨西哥至南美洲","descripcion":"翅膀黑色，前翅有醒目的红色宽带，因拟态而与艺神袖蝶几乎一模一样。飞行缓慢，取食花蜜和花粉，成虫可存活数周。是蝴蝶馆的经典物种，也是讲解缪勒拟态的理想范例。","vuelo":"缓慢，轻盈拍翅","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Heliconia safo', 'Heliconius sapho', 'Nymphalidae', 'México a Ecuador', 0, 'Alas negras con brillo azul acerado, una banda blanca en las anteriores y un borde blanco en las posteriores. Vuela con calma, suele mantenerse a media altura y visita flores con frecuencia. Su iridiscencia luce especialmente bien bajo luz natural y complementa a otras heliconias de patrón blanco y negro.', 'heliconius-sapho', '65–80 mm', 'Lento, a media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Sapho Longwing","region":"Mexico to Ecuador","descripcion":"Black wings with a steely blue sheen, a white forewing band and a white hindwing margin. It flies calmly, usually at mid-height, and visits flowers frequently. Its iridescence shows beautifully in natural light, and it pairs well with other black-and-white longwings in a mixed display.","vuelo":"Slow, mid-level","disponibilidad":"On request"},"it":{"nombre_comun":"Heliconius saffo","region":"Dal Messico all''Ecuador","descripcion":"Ali nere con riflessi blu acciaio, una fascia bianca sulle anteriori e un margine bianco sulle posteriori. Vola con calma, di solito a media altezza, e visita spesso i fiori. La sua iridescenza risalta alla luce naturale e si abbina bene ad altri Heliconius bianconeri.","vuelo":"Lento, a media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Héliconius sapho","region":"Du Mexique à l''Équateur","descripcion":"Ailes noires aux reflets bleu acier, avec une bande blanche à l''avant et une bordure blanche à l''arrière. Il vole calmement, généralement à mi-hauteur, et butine souvent. Son irisation ressort magnifiquement à la lumière naturelle et s''accorde bien avec d''autres héliconius noir et blanc.","vuelo":"Lent, à mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"萨福袖蝶","region":"墨西哥至厄瓜多尔","descripcion":"翅膀黑色，带钢蓝色光泽，前翅有白色横带，后翅边缘为白色。飞行平稳，多在中等高度活动，经常访花。其虹彩在自然光下格外动人，适合与其他黑白色袖蝶一同展示。","vuelo":"缓慢，中等高度","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Heliconia sara', 'Heliconius sara', 'Nymphalidae', 'México a la Amazonía', 0, 'Heliconia pequeña de alas negras con intenso brillo azul y bandas amarillentas o blancas en las anteriores. Es muy sociable: los adultos duermen en grupos sobre la misma rama y regresan a ella noche tras noche. Su tamaño compacto, su iridiscencia y sus dormideros comunales resultan muy atractivos para los visitantes.', 'heliconius-sara', '50–65 mm', 'Lento y ondulante', 'Bajo pedido', true, '{"en":{"nombre_comun":"Sara Longwing","region":"Mexico to the Amazon Basin","descripcion":"A small longwing with deep iridescent blue wings and pale yellow to white forewing bands. It is highly sociable, with adults roosting together on the same branch night after night. Its compact size, vivid sheen and communal roosts are a real draw for visitors.","vuelo":"Slow and fluttering","disponibilidad":"On request"},"it":{"nombre_comun":"Heliconius sara","region":"Dal Messico all''Amazzonia","descripcion":"Piccolo Heliconius dalle ali nere con intensi riflessi blu e fasce giallo pallido o bianche sulle anteriori. È molto socievole: gli adulti dormono in gruppo sullo stesso ramo, notte dopo notte. Dimensioni compatte, iridescenza e dormitori comuni attirano molto l''attenzione dei visitatori.","vuelo":"Lento e svolazzante","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Héliconius sara","region":"Du Mexique à l''Amazonie","descripcion":"Petit héliconius aux ailes d''un bleu irisé profond, avec des bandes jaune pâle à blanches à l''avant. Très sociable, il dort en groupe sur la même branche nuit après nuit. Sa petite taille, son éclat et ses dortoirs collectifs captivent les visiteurs.","vuelo":"Lent et voletant","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"萨拉袖蝶","region":"墨西哥至亚马孙流域","descripcion":"体型较小的袖蝶，翅面呈浓郁的虹彩蓝色，前翅有淡黄至白色条带。群居性强，成虫夜晚会聚集在同一根枝条上栖息，且每晚回到原处。小巧的体型、闪亮的光泽和集体栖息行为都很吸引游客。","vuelo":"缓慢，轻盈拍翅","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Hoja plateada', 'Hypna clytemnestra', 'Nymphalidae', 'México a Sudamérica', 0, 'Por encima es oscura con una ancha banda color crema; por debajo imita una hoja seca con pequeñas manchas plateadas. Tiene un vuelo rápido y potente, pero en el mariposario suele posarse con las alas cerradas y acudir a frutas fermentadas. El contraste entre ambas caras la hace ideal para hablar de camuflaje.', 'hypna-clytemnestra', '70–90 mm', 'Rápido y potente', 'Bajo pedido', true, '{"en":{"nombre_comun":"Silver-studded Leafwing","region":"Mexico to South America","descripcion":"Dark above with a broad cream band, while the underside mimics a dead leaf dotted with small silver marks. Its flight is fast and powerful, but in a flight house it often rests with wings closed and comes readily to fermenting fruit. The contrast between its two sides makes it perfect for explaining camouflage.","vuelo":"Fast and powerful","disponibilidad":"On request"},"it":{"nombre_comun":"Foglia argentata","region":"Dal Messico al Sudamerica","descripcion":"Scura sopra con un''ampia fascia color crema, mentre il rovescio imita una foglia secca punteggiata di piccole macchie argentee. Il volo è rapido e potente, ma in serra si posa spesso ad ali chiuse e si nutre volentieri di frutta fermentata. Il contrasto tra le due facce è ideale per spiegare il mimetismo criptico.","vuelo":"Rapido e potente","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Feuille argentée","region":"Du Mexique à l''Amérique du Sud","descripcion":"Sombre au-dessus avec une large bande crème, son revers imite une feuille morte parsemée de petites taches argentées. Son vol est rapide et puissant, mais en serre il se pose souvent ailes fermées et vient volontiers sur les fruits fermentés. Le contraste entre ses deux faces illustre parfaitement le camouflage.","vuelo":"Rapide et puissant","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"银星叶蛱蝶","region":"墨西哥至南美洲","descripcion":"翅正面深色，有一条宽阔的奶油色带；反面酷似枯叶，并点缀着细小的银色斑点。飞行迅速有力，但在蝴蝶馆中常合翅停歇，并喜欢取食发酵水果。正反两面的强烈对比非常适合用来讲解伪装。","vuelo":"快速有力","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tigre polimnia', 'Mechanitis polymnia', 'Nymphalidae', 'México a la Amazonía', 0, 'Alas alargadas con patrón atigrado de naranja, negro y amarillo, típico de los complejos miméticos neotropicales. Vuela bajo y despacio, casi flotando entre la vegetación sombreada, y visita flores con frecuencia. Su vuelo pausado permite observarla de cerca, y es una buena especie para ilustrar los anillos de mimetismo.', 'mechanitis-polymnia', '55–70 mm', 'Lento y bajo', 'Bajo pedido', true, '{"en":{"nombre_comun":"Disturbed Tigerwing","region":"Mexico to the Amazon Basin","descripcion":"Elongated wings in a tiger pattern of orange, black and yellow, typical of Neotropical mimicry rings. It flies low and slowly, almost floating through shaded vegetation, and visits flowers often. Its unhurried flight allows close viewing, and it is a good species for illustrating mimicry complexes.","vuelo":"Slow and low","disponibilidad":"On request"},"it":{"nombre_comun":"Ala tigrata polimnia","region":"Dal Messico all''Amazzonia","descripcion":"Ali allungate con disegno tigrato arancione, nero e giallo, tipico degli anelli mimetici neotropicali. Vola bassa e lenta, quasi fluttuando nella vegetazione ombreggiata, e visita spesso i fiori. Il volo tranquillo consente di osservarla da vicino ed è ideale per illustrare i complessi mimetici.","vuelo":"Lento e basso","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Aile-tigrée polymnia","region":"Du Mexique à l''Amazonie","descripcion":"Ailes allongées au motif tigré orange, noir et jaune, typique des cercles mimétiques néotropicaux. Il vole bas et lentement, semblant flotter dans la végétation ombragée, et butine fréquemment. Son vol posé permet une observation rapprochée et illustre bien les complexes mimétiques.","vuelo":"Lent et bas","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"多形虎纹绡蝶","region":"墨西哥至亚马孙流域","descripcion":"翅形狭长，呈橙、黑、黄三色虎纹，是新热带拟态环中的典型图案。在阴凉植被间低飞缓行，仿佛漂浮一般，经常访花。飞行从容，便于近距离观察，适合用来讲解拟态复合群。","vuelo":"缓慢低飞","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Ola azul', 'Myscelia cyaniris', 'Nymphalidae', 'México a Sudamérica noroccidental', 0, 'Por encima muestra bandas azul violeta iridiscentes sobre fondo oscuro con puntos blancos; por debajo es gris parda y críptica. Vuela rápido y en tramos cortos, se posa en troncos y se alimenta de frutas fermentadas. El destello azul al abrir las alas sorprende a los visitantes y aporta variedad a las estaciones de fruta.', 'myscelia-cyaniris', '50–65 mm', 'Rápido, en tramos cortos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Blue Wave","region":"Mexico to northwestern South America","descripcion":"The upperside shows iridescent violet-blue bands on a dark ground with white dots, while the underside is cryptic grey-brown. It flies fast in short bursts, perches on trunks and feeds at fermenting fruit. The flash of blue when it opens its wings surprises visitors and adds variety to fruit-feeding stations.","vuelo":"Fast, short bursts","disponibilidad":"On request"},"it":{"nombre_comun":"Onda blu","region":"Dal Messico al Sudamerica nord-occidentale","descripcion":"Il dritto mostra bande blu violaceo iridescenti su fondo scuro con puntini bianchi, mentre il rovescio è grigio-bruno e mimetico. Vola veloce a brevi scatti, si posa sui tronchi e si nutre di frutta fermentata. Il lampo blu quando apre le ali sorprende i visitatori e arricchisce le postazioni di frutta.","vuelo":"Rapido, a brevi scatti","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Vague bleue","region":"Du Mexique au nord-ouest de l''Amérique du Sud","descripcion":"Le dessus présente des bandes bleu violacé irisées sur fond sombre ponctué de blanc, tandis que le revers est gris-brun et cryptique. Il vole vite par courtes saccades, se pose sur les troncs et se nourrit de fruits fermentés. L''éclair bleu à l''ouverture des ailes surprend les visiteurs et diversifie les postes à fruits.","vuelo":"Rapide, par saccades","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"蓝波蛱蝶","region":"墨西哥至南美洲西北部","descripcion":"翅正面深色，带有虹彩蓝紫色条纹和白色小点；反面为灰褐色，具保护色。飞行迅速，常短距离冲刺，喜停在树干上并取食发酵水果。展翅时闪现的蓝光令游客惊喜，也让水果喂食区更加丰富。","vuelo":"快速，短距冲刺","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Búho de banda naranja', 'Opsiphanes tamarindi', 'Nymphalidae', 'México a Sudamérica', 0, 'Mariposa robusta de alas pardas con una banda anaranjada en las anteriores y ocelos en la cara inferior de las posteriores. Es activa al amanecer y al atardecer; durante el día descansa con las alas cerradas y acude a frutas fermentadas. Complementa bien a los búhos Caligo y muestra una faceta crepuscular del mariposario.', 'opsiphanes-tamarindi', '75–90 mm', 'Crepuscular, rápido', 'Bajo pedido', true, '{"en":{"nombre_comun":"Tamarindi Owlet","region":"Mexico to South America","descripcion":"A stout butterfly with brown wings, an orange forewing band and eyespots on the hindwing underside. It is most active at dawn and dusk, resting with wings closed by day and coming to fermenting fruit. It pairs well with Caligo owl butterflies and showcases the crepuscular side of a butterfly house.","vuelo":"Crepuscular, fast","disponibilidad":"On request"},"it":{"nombre_comun":"Piccola civetta tamarindi","region":"Dal Messico al Sudamerica","descripcion":"Farfalla robusta dalle ali brune, con una fascia arancione sulle anteriori e ocelli sul rovescio delle posteriori. È attiva soprattutto all''alba e al tramonto; di giorno riposa ad ali chiuse e si nutre di frutta fermentata. Si abbina bene alle farfalle civetta Caligo e mostra il lato crepuscolare della serra.","vuelo":"Crepuscolare, rapido","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Petit hibou tamarindi","region":"Du Mexique à l''Amérique du Sud","descripcion":"Papillon trapu aux ailes brunes, orné d''une bande orange à l''avant et d''ocelles au revers des ailes postérieures. Surtout actif à l''aube et au crépuscule, il se repose ailes fermées le jour et vient sur les fruits fermentés. Il complète bien les papillons hiboux Caligo et révèle la facette crépusculaire d''une serre.","vuelo":"Crépusculaire, rapide","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"橙带鸮环蝶","region":"墨西哥至南美洲","descripcion":"体型粗壮，翅膀褐色，前翅有橙色带，后翅反面具眼斑。主要在黎明和黄昏活动，白天合翅停歇，喜食发酵水果。与猫头鹰蝶搭配展示效果很好，能呈现蝴蝶馆中晨昏活动的一面。","vuelo":"晨昏活动，快速","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Cola de golondrina de manchas rojas', 'Papilio anchisiades', 'Papilionidae', 'Sur de EE. UU. a Argentina', 0, 'Papiliónido negro sin colas, con una mancha rosada o rojo carmín en las alas posteriores. Vuela a media altura y visita flores agitando las alas sin cesar mientras se alimenta. Su gran tamaño y su movimiento constante aportan dinamismo a la exhibición, y la oruga que imita excremento de ave es un excelente recurso educativo.', 'papilio-anchisiades', '80–100 mm', 'Aleteo continuo, media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Ruby-spotted Swallowtail","region":"Southern USA to Argentina","descripcion":"A tailless black swallowtail with a pink to ruby patch on the hindwings. It flies at mid-height and keeps its wings fluttering while feeding at flowers. Its size and constant motion bring energy to a display, and its bird-dropping-mimic caterpillar makes an excellent teaching subject.","vuelo":"Fluttering, mid-level","disponibilidad":"On request"},"it":{"nombre_comun":"Papilio dalle macchie rubino","region":"Dal sud degli Stati Uniti all''Argentina","descripcion":"Papilionide nero privo di code, con una macchia da rosa a rosso rubino sulle ali posteriori. Vola a media altezza e continua a battere le ali mentre si nutre sui fiori. Le dimensioni e il movimento costante animano l''esposizione, e il bruco che imita un escremento d''uccello è un ottimo spunto didattico.","vuelo":"Battito continuo, media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Porte-queue à taches rubis","region":"Du sud des États-Unis à l''Argentine","descripcion":"Papilionidé noir dépourvu de queues, avec une tache rose à rouge rubis sur les ailes postérieures. Il vole à mi-hauteur et continue de battre des ailes en butinant. Sa taille et son mouvement constant dynamisent l''exposition, et sa chenille imitant une fiente d''oiseau offre un excellent support pédagogique.","vuelo":"Battements continus, mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"红斑黑凤蝶","region":"美国南部至阿根廷","descripcion":"无尾突的黑色凤蝶，后翅有粉红至宝石红色斑块。多在中等高度飞行，访花取食时翅膀不停扇动。体型大、动感强，能为展区增添活力；其幼虫拟态鸟粪，也是很好的科普素材。","vuelo":"持续扇翅，中等高度","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Corazón de ganado', 'Parides arcas', 'Papilionidae', 'México a Sudamérica noroccidental', 0, 'Alas negras con manchas rojo carmín en las posteriores; el macho luce además un parche verdoso en las anteriores. Vuela despacio y bajo, y aletea continuamente mientras liba en las flores. Es tóxica para los depredadores gracias a su planta hospedera, Aristolochia, y resulta una especie elegante y fácil de observar.', 'parides-arcas', '65–80 mm', 'Lento, aleteo continuo', 'Bajo pedido', true, '{"en":{"nombre_comun":"Arcas Cattleheart","region":"Mexico to northwestern South America","descripcion":"Black wings with crimson hindwing spots, and males also bear a greenish patch on the forewing. It flies slowly and low, fluttering continuously as it sips nectar. Chemically protected by its Aristolochia host plant, it is an elegant, easy-to-watch species that rewards close observation.","vuelo":"Slow, constant fluttering","disponibilidad":"On request"},"it":{"nombre_comun":"Cuore di bue arcas","region":"Dal Messico al Sudamerica nord-occidentale","descripcion":"Ali nere con macchie cremisi sulle posteriori; il maschio presenta anche una chiazza verdastra sulle anteriori. Vola lento e basso, battendo le ali senza sosta mentre sugge il nettare. Protetta chimicamente dalla pianta ospite Aristolochia, è una specie elegante e facile da osservare da vicino.","vuelo":"Lento, battito continuo","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Cœur-de-bœuf arcas","region":"Du Mexique au nord-ouest de l''Amérique du Sud","descripcion":"Ailes noires ornées de taches cramoisies à l''arrière ; le mâle porte en plus une plage verdâtre à l''avant. Il vole lentement et bas, battant des ailes sans arrêt en butinant. Protégé chimiquement par sa plante hôte, l''aristoloche, c''est une espèce élégante et facile à observer de près.","vuelo":"Lent, battements continus","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"阿卡斯番凤蝶","region":"墨西哥至南美洲西北部","descripcion":"翅膀黑色，后翅有深红色斑点，雄蝶前翅还有一块绿色斑。低空缓慢飞行，吸食花蜜时翅膀不停扇动。幼虫取食马兜铃，因而成虫体内带有毒素、少受天敌捕食，是一种优雅且便于近距离观察的物种。","vuelo":"缓慢，持续扇翅","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Corazón de ganado', 'Parides iphidamas', 'Papilionidae', 'México a Sudamérica', 0, 'Mariposa negra aterciopelada con manchas rosado-rojizas en las alas posteriores y, en los machos, un parche verde metálico en las anteriores. Vuela bajo y pausado entre la vegetación y aletea sin parar mientras se alimenta en las flores. Su contraste de colores y su actividad constante la hacen muy vistosa en exhibición.', 'parides-iphidamas', '65–80 mm', 'Lento, bajo y aleteado', 'Bajo pedido', true, '{"en":{"nombre_comun":"Iphidamas Cattleheart","region":"Mexico to South America","descripcion":"A velvety black swallowtail with rose-red hindwing spots, the males adding a metallic green patch on the forewings. It flies low and unhurried through the plantings and keeps fluttering while it nectars at flowers. Its bold colors and steady activity make it a standout display species.","vuelo":"Slow, low, fluttering","disponibilidad":"On request"},"it":{"nombre_comun":"Cuore di bue di Iphidamas","region":"Dal Messico al Sud America","descripcion":"Farfalla nero vellutato con macchie rosso-rosate sulle ali posteriori; i maschi mostrano anche una macchia verde metallico sulle anteriori. Vola bassa e senza fretta tra la vegetazione e continua a battere le ali mentre si nutre sui fiori. I colori netti e l''attività costante la rendono molto spettacolare in esposizione.","vuelo":"Lento, basso, frullante","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Cœur-de-bœuf d''Iphidamas","region":"Du Mexique à l''Amérique du Sud","descripcion":"Papillon noir velouté aux taches rose-rouge sur les ailes postérieures, les mâles portant en plus une plage vert métallique sur les antérieures. Il vole bas et sans hâte parmi les plantes et bat des ailes en continu en butinant. Ses couleurs contrastées et son activité constante en font une espèce très remarquée en volière.","vuelo":"Lent, bas et battu","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"红斑番凤蝶","region":"墨西哥至南美洲","descripcion":"翅面呈天鹅绒般的黑色，后翅有玫红色斑，雄蝶前翅另有金属绿色斑块。它在植物间低空缓慢飞行，访花吸蜜时翅膀仍不停扇动。鲜明的色彩对比和持续的活跃表现，使其成为展馆中非常醒目的品种。","vuelo":"低空缓飞，频繁振翅","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Azufre anaranjado', 'Phoebis argante', 'Pieridae', 'México a Sudamérica', 0, 'Los machos son de un naranja albaricoque intenso y uniforme; las hembras, amarillo anaranjado con marcas oscuras más marcadas. Vuela rápido y directo, se detiene con frecuencia en flores y a veces en suelos húmedos. Aporta destellos de color cálido y mucho movimiento a cualquier mariposario.', 'phoebis-argante', '55–70 mm', 'Rápido y directo', 'Bajo pedido', true, '{"en":{"nombre_comun":"Apricot Sulphur","region":"Mexico to South America","descripcion":"Males are a rich, even apricot orange, while females are yellow-orange with bolder dark markings. It flies fast and direct, stopping often at flowers and sometimes at damp ground. A reliable source of warm color and constant movement in any flight house.","vuelo":"Fast and direct","disponibilidad":"On request"},"it":{"nombre_comun":"Zolfo albicocca","region":"Dal Messico al Sud America","descripcion":"I maschi sono di un arancio albicocca intenso e uniforme; le femmine sono giallo-arancio con disegni scuri più marcati. Vola veloce e diritta, fermandosi spesso sui fiori e talvolta sul terreno umido. Porta lampi di colore caldo e movimento continuo in qualsiasi serra.","vuelo":"Veloce e diretto","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Soufré abricot","region":"Du Mexique à l''Amérique du Sud","descripcion":"Les mâles sont d''un orange abricot vif et uniforme ; les femelles, jaune orangé, portent des marques sombres plus nettes. Son vol est rapide et direct, avec de fréquentes haltes sur les fleurs et parfois sur le sol humide. Elle apporte des touches de couleur chaude et beaucoup de mouvement en volière.","vuelo":"Rapide et direct","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"杏黄粉蝶","region":"墨西哥至南美洲","descripcion":"雄蝶通体呈浓郁均匀的杏橙色，雌蝶为黄橙色，暗色斑纹更明显。飞行迅速而直接，经常停在花上吸蜜，有时也会停在潮湿地面。能为蝴蝶馆带来温暖的色彩和持续的动感。","vuelo":"快速直线飞行","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Azufre de barra naranja', 'Phoebis philea', 'Pieridae', 'México a Sudamérica', 0, 'Una de las pieridas más grandes de América: el macho es amarillo intenso con una barra naranja en el ala anterior y el borde de la posterior anaranjado; la hembra varía entre amarillo y tonos más oscuros. Vuela con fuerza y visita con avidez flores rojas y anaranjadas. Muy llamativa y activa en exhibición.', 'phoebis-philea', '70–90 mm', 'Rápido y enérgico', 'Bajo pedido', true, '{"en":{"nombre_comun":"Orange-barred Sulphur","region":"Mexico to South America","descripcion":"One of the largest sulphurs in the Americas: males are bright yellow with an orange bar across the forewing and orange-edged hindwings, while females range from yellow to deeper, more patterned forms. A strong flier that eagerly works red and orange flowers, it is showy and highly active on display.","vuelo":"Fast and powerful","disponibilidad":"On request"},"it":{"nombre_comun":"Zolfo a barra arancione","region":"Dal Messico al Sud America","descripcion":"Una delle pieridi più grandi delle Americhe: il maschio è giallo acceso con una barra arancione sull''ala anteriore e il margine delle posteriori aranciato, mentre la femmina varia dal giallo a forme più scure. Volatrice potente, visita con avidità fiori rossi e arancioni. Vistosa e molto attiva in esposizione.","vuelo":"Veloce e potente","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Soufré à barre orange","region":"Du Mexique à l''Amérique du Sud","descripcion":"L''un des plus grands soufrés des Amériques : le mâle, jaune vif, porte une barre orange sur l''aile antérieure et une bordure orangée aux postérieures, tandis que la femelle va du jaune à des formes plus sombres. Voilier puissant, il butine avidement les fleurs rouges et orange. Spectaculaire et très actif en volière.","vuelo":"Rapide et puissant","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"橙斑黄粉蝶","region":"墨西哥至南美洲","descripcion":"美洲体型最大的黄粉蝶之一：雄蝶亮黄色，前翅有一道橙色横斑，后翅边缘带橙色；雌蝶从黄色到斑纹更深的类型均有。飞行有力，喜欢造访红色和橙色花朵。外观醒目，在展馆中非常活跃。","vuelo":"快速有力","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Azufre sin nubes', 'Phoebis sennae', 'Pieridae', 'América', 0, 'Mariposa de un amarillo limón limpio, casi sin marcas en los machos y con pequeños puntos oscuros en las hembras. Vuela rápido y alto, pero baja constantemente a libar en flores tubulares. Resistente y fácil de manejar, llena el mariposario de destellos amarillos.', 'phoebis-sennae', '55–70 mm', 'Rápido, a media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Cloudless Sulphur","region":"The Americas","descripcion":"A clean lemon-yellow butterfly, nearly unmarked in males and lightly dotted in females. It flies fast and fairly high but keeps dropping down to nectar at tubular flowers. Hardy and easy to handle, it fills a flight house with flashes of bright yellow.","vuelo":"Fast, mid-level","disponibilidad":"On request"},"it":{"nombre_comun":"Zolfo senza nuvole","region":"Americhe","descripcion":"Farfalla giallo limone brillante, quasi priva di disegni nei maschi e con piccoli punti scuri nelle femmine. Vola veloce e piuttosto in alto, ma scende di continuo a nutrirsi sui fiori tubulari. Robusta e facile da gestire, riempie la serra di lampi gialli.","vuelo":"Veloce, a media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Soufré sans nuage","region":"Amériques","descripcion":"Papillon jaune citron éclatant, presque sans marques chez le mâle et légèrement ponctué chez la femelle. Son vol est rapide et assez haut, mais il redescend sans cesse butiner les fleurs tubulaires. Robuste et facile à manipuler, il remplit la volière d''éclairs jaunes.","vuelo":"Rapide, mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"无云黄粉蝶","region":"美洲","descripcion":"通体柠檬黄色，雄蝶几乎无斑纹，雌蝶带有细小暗点。飞行迅速且较高，但会频繁下降到管状花上吸蜜。体质强健、易于管理，能让蝴蝶馆处处闪现明黄色彩。","vuelo":"快速，中等高度","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Polilla cuatro espejos', 'Rothschildia lebeau', 'Saturniidae', 'México a Sudamérica', 0, 'Gran polilla de la seda en tonos canela y rojizos, con una ventana translúcida en cada ala que parece un pequeño espejo. Los adultos no se alimentan y viven solo unos días, activos de noche y quietos durante el día, lo que permite observarlos de cerca. El capullo sedoso y la emergencia son un gran atractivo educativo.', 'rothschildia-lebeau', '100–140 mm', 'Nocturno', 'Bajo pedido', true, '{"en":{"nombre_comun":"Four-mirror Silk Moth","region":"Mexico to South America","descripcion":"A large silk moth in cinnamon and rusty tones, each wing set with a translucent window like a small mirror. Adults do not feed and live only a few days; they fly at night and rest motionless by day, so visitors can study them up close. The silken cocoon and emergence make a strong educational display.","vuelo":"Nocturnal","disponibilidad":"On request"},"it":{"nombre_comun":"Falena dai quattro specchi","region":"Dal Messico al Sud America","descripcion":"Grande falena della seta dai toni cannella e ruggine, con una finestra trasparente su ogni ala simile a un piccolo specchio. Gli adulti non si nutrono e vivono solo pochi giorni; volano di notte e di giorno restano immobili, così il pubblico può osservarli da vicino. Il bozzolo di seta e lo sfarfallamento sono di grande valore didattico.","vuelo":"Notturno","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Bombyx à quatre miroirs","region":"Du Mexique à l''Amérique du Sud","descripcion":"Grand papillon de nuit séricigène aux tons cannelle et rouille, chaque aile portant une fenêtre translucide semblable à un petit miroir. Les adultes ne se nourrissent pas et ne vivent que quelques jours ; actifs la nuit, ils restent immobiles le jour et s''observent de près. Le cocon soyeux et l''émergence ont une forte valeur pédagogique.","vuelo":"Nocturne","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"四镜大蚕蛾","region":"墨西哥至南美洲","descripcion":"大型天蚕蛾，体色为肉桂色与锈红色，每片翅上都有一块半透明的窗斑，犹如小镜子。成虫不进食，寿命仅数天，夜间活动、白天静止不动，便于游客近距离观察。丝质茧和羽化过程极具科普展示价值。","vuelo":"夜行性","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Página de puntas rojizas', 'Siproeta epaphus', 'Nymphalidae', 'México a Sudamérica', 0, 'Alas marrón oscuro atravesadas por una amplia banda blanca y con las puntas de un cálido tono óxido. Planea con elegancia a media altura y se posa a menudo con las alas abiertas sobre flores y hojas. Tranquila y fácil de fotografiar, es una favorita del público.', 'siproeta-epaphus', '70–85 mm', 'Planeado, a media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Rusty-tipped Page","region":"Mexico to South America","descripcion":"Dark chocolate wings are crossed by a broad white band and finished with warm rust-orange tips. It glides gracefully at mid-level and often settles with wings spread on flowers and foliage. Calm and easy to photograph, it quickly becomes a visitor favorite.","vuelo":"Gliding, mid-level","disponibilidad":"On request"},"it":{"nombre_comun":"Paggio dalle punte ruggine","region":"Dal Messico al Sud America","descripcion":"Ali marrone scuro attraversate da un''ampia fascia bianca e con gli apici di un caldo color ruggine. Plana con eleganza a media altezza e si posa spesso ad ali aperte su fiori e foglie. Tranquilla e facile da fotografare, conquista subito i visitatori.","vuelo":"Planato, a media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Page à pointes rouille","region":"Du Mexique à l''Amérique du Sud","descripcion":"Ailes brun foncé traversées d''une large bande blanche et terminées par des pointes d''un chaud orange rouille. Il plane avec élégance à mi-hauteur et se pose souvent ailes ouvertes sur les fleurs et le feuillage. Calme et facile à photographier, il devient vite un favori du public.","vuelo":"Plané, mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"锈尖帘蛱蝶","region":"墨西哥至南美洲","descripcion":"深褐色翅面横贯一条宽阔的白色带，翅尖呈温暖的锈橙色。它在中等高度优雅滑翔，常张开双翅停在花朵和叶片上。性情安静、易于拍摄，很快就能成为游客的最爱。","vuelo":"中等高度滑翔","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Mariposa búho', 'Caligo eurilochus', 'Nymphalidae', 'México a Sudamérica', 0, 'Mariposa enorme cuyo reverso, finamente veteado en pardos y grises, luce un gran ocelo que recuerda el ojo de un búho. Pasa el día posada en troncos y se activa al amanecer y al atardecer, cuando acude a frutas fermentadas. Su tamaño y su aspecto la convierten en una pieza central del mariposario.', 'caligo-eurilochus', '120–150 mm', 'Crepuscular, bajo', 'Bajo pedido', true, '{"en":{"nombre_comun":"Forest Giant Owl","region":"Mexico to South America","descripcion":"A huge butterfly whose finely patterned brown-and-grey underside carries a large eyespot resembling an owl''s eye. It spends the day resting on trunks and becomes active at dawn and dusk, when it comes to fermenting fruit. Its size and striking look make it a centerpiece of any flight house.","vuelo":"Crepuscular, low","disponibilidad":"On request"},"it":{"nombre_comun":"Farfalla civetta","region":"Dal Messico al Sud America","descripcion":"Farfalla enorme il cui rovescio, finemente venato di bruni e grigi, porta un grande ocello simile all''occhio di una civetta. Trascorre il giorno posata sui tronchi e si attiva all''alba e al tramonto, quando si nutre di frutta fermentata. Dimensioni e aspetto la rendono un punto focale della serra.","vuelo":"Crepuscolare, basso","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Papillon hibou","region":"Du Mexique à l''Amérique du Sud","descripcion":"Papillon géant dont le revers, finement marbré de bruns et de gris, porte un grand ocelle rappelant l''œil d''un hibou. Il passe la journée posé sur les troncs et s''active à l''aube et au crépuscule pour se nourrir de fruits fermentés. Sa taille et son allure en font une pièce maîtresse de la volière.","vuelo":"Crépusculaire, bas","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"森林猫头鹰环蝶","region":"墨西哥至南美洲","descripcion":"体型巨大，翅反面布满细密的褐灰色纹理，并有一枚酷似猫头鹰眼睛的大眼斑。白天静栖于树干上，清晨和黄昏时分活跃，常到发酵水果上取食。硕大的体型和独特外观使其成为蝴蝶馆的焦点展品。","vuelo":"晨昏活动，低飞","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Búho de banda amarilla', 'Caligo atreus', 'Nymphalidae', 'México a Sudamérica', 0, 'Una de las mariposas búho más grandes: por encima es azul violáceo oscuro con una ancha banda amarilla en el ala posterior, y por debajo muestra los típicos ocelos de búho. Descansa en troncos durante el día y vuela al atardecer hacia frutas maduras. Espectacular al abrir las alas.', 'caligo-atreus', '120–160 mm', 'Crepuscular, pesado', 'Bajo pedido', true, '{"en":{"nombre_comun":"Yellow-edged Giant Owl","region":"Mexico to South America","descripcion":"One of the largest owl butterflies: the upperside is deep violet-blue with a broad yellow band on the hindwing, while the underside shows the classic owl eyespots. It rests on trunks by day and flies toward ripe fruit at dusk. Truly spectacular when it opens its wings.","vuelo":"Crepuscular, heavy","disponibilidad":"On request"},"it":{"nombre_comun":"Civetta gigante bordata di giallo","region":"Dal Messico al Sud America","descripcion":"Una delle farfalle civetta più grandi: il dritto è blu violaceo scuro con un''ampia fascia gialla sull''ala posteriore, mentre il rovescio mostra i classici ocelli da civetta. Di giorno riposa sui tronchi e al tramonto vola verso la frutta matura. Spettacolare quando apre le ali.","vuelo":"Crepuscolare, pesante","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hibou géant à bande jaune","region":"Du Mexique à l''Amérique du Sud","descripcion":"L''un des plus grands papillons hiboux : le dessus est bleu violacé sombre avec une large bande jaune sur l''aile postérieure, et le revers porte les ocelles typiques du genre. Il se repose sur les troncs le jour et vole vers les fruits mûrs au crépuscule. Spectaculaire lorsqu''il ouvre les ailes.","vuelo":"Crépusculaire, lourd","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"黄带猫头鹰环蝶","region":"墨西哥至南美洲","descripcion":"最大型的猫头鹰蝶之一：翅正面为深紫蓝色，后翅有一条宽阔的黄色带，反面则是典型的猫头鹰眼斑。白天停栖在树干上，黄昏时飞向成熟水果取食。展翅时极为壮观。","vuelo":"晨昏活动，飞行沉稳","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Brassolis del istmo', 'Brassolis isthmia', 'Nymphalidae', 'Costa Rica a Colombia', 0, 'Pariente robusta de las mariposas búho, de color pardo oscuro con una banda anaranjada en el ala anterior. Permanece quieta durante el día y se activa al atardecer con un vuelo rápido y algo errático. Ofrece a los visitantes una mirada distinta a las mariposas crepusculares del trópico.', 'brassolis-isthmia', '70–90 mm', 'Crepuscular, rápido', 'Bajo pedido', true, '{"en":{"nombre_comun":"Isthmian Brassolis","region":"Costa Rica to Colombia","descripcion":"A stout relative of the owl butterflies, dark brown with an orange band across the forewing. It stays still through the day and comes alive at dusk with a quick, somewhat erratic flight. It gives visitors a different window into the tropics'' twilight-flying butterflies.","vuelo":"Crepuscular, fast","disponibilidad":"On request"},"it":{"nombre_comun":"Brassolis dell''istmo","region":"Dalla Costa Rica alla Colombia","descripcion":"Robusta parente delle farfalle civetta, bruno scuro con una fascia arancione sull''ala anteriore. Resta immobile durante il giorno e si anima al tramonto con un volo rapido e un po'' irregolare. Offre ai visitatori uno sguardo diverso sulle farfalle crepuscolari dei tropici.","vuelo":"Crepuscolare, rapido","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Brassolis de l''isthme","region":"Du Costa Rica à la Colombie","descripcion":"Proche parent trapu des papillons hiboux, brun foncé avec une bande orange sur l''aile antérieure. Immobile pendant la journée, il s''anime au crépuscule d''un vol rapide et un peu erratique. Il offre aux visiteurs un autre regard sur les papillons crépusculaires des tropiques.","vuelo":"Crépusculaire, rapide","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"地峡棕榈环蝶","region":"哥斯达黎加至哥伦比亚","descripcion":"猫头鹰蝶的近亲，身体粗壮，翅为深褐色，前翅有一条橙色带。白天静止不动，黄昏时开始活跃，飞行迅速而略显无规律。能让游客认识热带地区晨昏活动的蝴蝶。","vuelo":"晨昏活动，飞行迅速","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Blanca limona', 'Ascia limona', 'Pieridae', 'Centroamérica', 0, 'Mariposa blanca de tamaño mediano con finas marcas oscuras cerca de los bordes de las alas. Vuela de forma ágil y constante a baja altura, visitando flores con frecuencia. Aporta luminosidad y movimiento al mariposario y combina bien con especies de colores intensos.', 'ascia-limona', '45–60 mm', 'Ágil, a baja altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Limona White","region":"Central America","descripcion":"A medium-sized white butterfly with fine dark markings near the wing edges. It flies nimbly and steadily close to the ground, visiting flowers often. It brings brightness and movement to a flight house and pairs well with more vividly colored species.","vuelo":"Nimble, low","disponibilidad":"On request"},"it":{"nombre_comun":"Bianca limona","region":"America Centrale","descripcion":"Farfalla bianca di taglia media con sottili disegni scuri vicino ai margini delle ali. Vola agile e costante a bassa quota, visitando spesso i fiori. Porta luminosità e movimento nella serra e si abbina bene alle specie dai colori più intensi.","vuelo":"Agile, basso","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Piéride limona","region":"Amérique centrale","descripcion":"Papillon blanc de taille moyenne aux fines marques sombres près du bord des ailes. Son vol est agile et régulier, près du sol, avec de fréquentes visites aux fleurs. Il apporte lumière et mouvement à la volière et s''associe bien aux espèces aux couleurs vives.","vuelo":"Agile, bas","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"利蒙白粉蝶","region":"中美洲","descripcion":"中等体型的白色蝴蝶，翅缘附近有细小的暗色斑纹。飞行灵活持续，贴近地面，常常访花。能为蝴蝶馆增添明亮感与动感，并与色彩浓烈的品种相得益彰。","vuelo":"灵活低飞","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Hermana de celda bandeada', 'Adelpha fessonia', 'Nymphalidae', 'México a Panamá', 0, 'Alas pardo oscuro con una banda blanca continua y un parche anaranjado cerca de la punta del ala anterior. Alterna aleteos rápidos con planeos cortos y suele posarse con las alas abiertas. Se alimenta en flores y frutas maduras, lo que facilita su observación en exhibición.', 'adelpha-fessonia', '50–60 mm', 'Rápido, con planeos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Band-celled Sister","region":"Mexico to Panama","descripcion":"Dark brown wings carry a continuous white band and an orange patch near the forewing tip. It alternates quick wingbeats with short glides and usually perches with wings open. It feeds at flowers and ripe fruit, making it easy to observe on display.","vuelo":"Quick, with glides","disponibilidad":"On request"},"it":{"nombre_comun":"Sorella a cella fasciata","region":"Dal Messico a Panama","descripcion":"Ali bruno scuro con una fascia bianca continua e una macchia arancione vicino all''apice dell''ala anteriore. Alterna battiti rapidi a brevi planate e si posa di solito ad ali aperte. Si nutre su fiori e frutta matura, il che la rende facile da osservare in esposizione.","vuelo":"Rapido, con planate","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Sœur à cellule barrée","region":"Du Mexique au Panama","descripcion":"Ailes brun foncé ornées d''une bande blanche continue et d''une tache orange près de l''apex de l''aile antérieure. Elle alterne battements rapides et courts vols planés, et se pose généralement ailes ouvertes. Elle se nourrit sur les fleurs et les fruits mûrs, ce qui la rend facile à observer.","vuelo":"Rapide, avec planés","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"带室姊妹蛱蝶","region":"墨西哥至巴拿马","descripcion":"深褐色翅面上有一条连贯的白色带，前翅近顶角处有橙色斑块。飞行时快速振翅与短距离滑翔交替，停栖时通常张开双翅。会在花朵和成熟水果上取食，展出时便于观察。","vuelo":"快速振翅，间有滑翔","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Mariposa espejitos', 'Agraulis vanillae', 'Nymphalidae', 'América', 0, 'Alas alargadas de un naranja brillante por encima y, por debajo, adornadas con manchas plateadas que destellan como pequeños espejos. Vuela rápido y bajo, visita flores sin descanso y se reproduce en pasifloras. Muy resistente y activa, llena de color cualquier mariposario.', 'agraulis-vanillae', '65–80 mm', 'Rápido y bajo', 'Bajo pedido', true, '{"en":{"nombre_comun":"Gulf Fritillary","region":"The Americas","descripcion":"Long, bright orange wings above and, below, silver spots that flash like tiny mirrors when it lands. It flies fast and low, visits flowers tirelessly and breeds on passionvines. Hardy and very active, it brings vivid color to any flight house.","vuelo":"Fast and low","disponibilidad":"On request"},"it":{"nombre_comun":"Fritillaria del Golfo","region":"Americhe","descripcion":"Ali allungate arancione brillante sul dritto e, sul rovescio, macchie argentate che brillano come piccoli specchi quando si posa. Vola veloce e bassa, visita i fiori senza sosta e si riproduce sulle passiflore. Robusta e molto attiva, porta colori vivaci in qualsiasi serra.","vuelo":"Veloce e basso","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Fritillaire du Golfe","region":"Amériques","descripcion":"Ailes allongées d''un orange vif au-dessus et, au revers, des taches argentées qui scintillent comme de petits miroirs lorsqu''il se pose. Il vole vite et bas, butine sans relâche et se reproduit sur les passiflores. Robuste et très actif, il apporte des couleurs éclatantes à toute volière.","vuelo":"Rapide et bas","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"银纹红袖蝶","region":"美洲","descripcion":"翅形狭长，正面为亮橙色，反面缀有银色斑点，停落时如小镜子般闪烁。飞行快速且贴近地面，不停访花，以西番莲为寄主植物繁殖。体质强健、非常活跃，能为任何蝴蝶馆带来鲜艳色彩。","vuelo":"快速低飞","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Pavorreal bandeado', 'Anartia fatima', 'Nymphalidae', 'México a Panamá', 0, 'Mariposa pardo oscuro con una banda clara, blanca o amarillenta, que cruza ambas alas y una barra roja en el ala posterior. Vuela bajo, con aleteos cortos entre flores pequeñas, y se posa a menudo con las alas abiertas. Muy fácil de ver y de mantener, ideal para exhibiciones abiertas al público.', 'anartia-fatima', '50–60 mm', 'Bajo, entre flores', 'Bajo pedido', true, '{"en":{"nombre_comun":"Banded Peacock","region":"Mexico to Panama","descripcion":"A dark brown butterfly with a pale white-to-cream band across both wings and a red bar on the hindwing. It flies low in short hops between small flowers and often basks with wings spread. Easy to spot and easy to keep, it suits busy public exhibits well.","vuelo":"Low, flower to flower","disponibilidad":"On request"},"it":{"nombre_comun":"Pavone fasciato","region":"Dal Messico a Panama","descripcion":"Farfalla bruno scuro con una fascia chiara, bianca o crema, che attraversa entrambe le ali e una barra rossa sull''ala posteriore. Vola bassa con brevi spostamenti tra fiori piccoli e si posa spesso ad ali aperte. Facile da vedere e da allevare, è ideale per esposizioni molto frequentate.","vuelo":"Basso, tra i fiori","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Paon rayé","region":"Du Mexique au Panama","descripcion":"Papillon brun foncé traversé d''une bande claire, blanche à crème, sur les deux ailes, avec une barre rouge sur l''aile postérieure. Il vole bas par petits bonds entre les petites fleurs et se pose souvent ailes ouvertes. Facile à observer et à maintenir, il convient parfaitement aux expositions très fréquentées.","vuelo":"Bas, de fleur en fleur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"带纹孔雀蛱蝶","region":"墨西哥至巴拿马","descripcion":"深褐色蝴蝶，一条白色至乳黄色的浅色带横贯前后翅，后翅还有一道红色横斑。它在小花之间低空短距离穿梭，常张开双翅晒太阳。容易观察、易于饲养，非常适合游客众多的展出场所。","vuelo":"低飞，穿梭花间","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Azufre blanco de ala angulosa', 'Anteos clorinde', 'Pieridae', 'México a Sudamérica', 0, 'Gran pierida de color blanco verdoso con una mancha amarilla anaranjada en el ala anterior y alas de puntas anguladas. Cuando se posa con las alas cerradas se confunde con una hoja pálida. Su vuelo es potente y alto, y baja a libar en flores grandes, dando dinamismo al mariposario.', 'anteos-clorinde', '75–90 mm', 'Potente y alto', 'Bajo pedido', true, '{"en":{"nombre_comun":"White Angled-Sulphur","region":"Mexico to South America","descripcion":"A large, pale greenish-white sulphur with a yellow-orange bar on the forewing and distinctly angled wingtips. Perched with wings closed, it passes for a pale leaf. Its flight is powerful and high, dropping down to nectar at large blooms and adding energy to a flight house.","vuelo":"Powerful and high","disponibilidad":"On request"},"it":{"nombre_comun":"Zolfo bianco ad ali angolate","region":"Dal Messico al Sud America","descripcion":"Grande pieride bianco verdastra con una macchia giallo-arancio sull''ala anteriore e apici alari nettamente angolati. Posata ad ali chiuse, sembra una foglia pallida. Il volo è potente e alto, e scende a nutrirsi sui fiori grandi, dando dinamismo alla serra.","vuelo":"Potente e alto","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Soufré blanc à ailes anguleuses","region":"Du Mexique à l''Amérique du Sud","descripcion":"Grande piéride blanc verdâtre marquée d''une tache jaune orangé sur l''aile antérieure, aux apex nettement anguleux. Posée ailes fermées, elle ressemble à une feuille pâle. Son vol est puissant et haut, et elle descend butiner les grandes fleurs, donnant du dynamisme à la volière.","vuelo":"Puissant et haut","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"白角翅黄粉蝶","region":"墨西哥至南美洲","descripcion":"大型粉蝶，翅为淡绿白色，前翅有黄橙色斑，翅尖明显呈角状。合翅停栖时宛如一片淡色叶子。飞行强劲且较高，会下降到大型花朵上吸蜜，为蝴蝶馆增添活力。","vuelo":"强劲高飞","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Prepona de banda azul', 'Archaeoprepona demophon', 'Nymphalidae', 'México a Sudamérica', 0, 'Mariposa robusta de alas negras cruzadas por una ancha banda azul verdosa, con el reverso pardo y críptico que la camufla al posarse. Vuela con gran potencia y acude con avidez a la fruta fermentada, donde se deja observar de cerca. Aporta tamaño, velocidad y un destello metálico muy llamativo a cualquier mariposario.', 'archaeoprepona-demophon', '90–110 mm', 'Muy rápido y potente', 'Bajo pedido', true, '{"en":{"nombre_comun":"One-spotted Prepona","region":"Mexico to South America","descripcion":"A powerfully built butterfly with black wings crossed by a broad blue-green band, while the brown, cryptic underside hides it the moment it lands. It flies fast and strong but comes readily to fermenting fruit, where visitors can watch it at close range. It brings size, speed and a flash of metallic color to any flight house.","vuelo":"Very fast and powerful","disponibilidad":"On request"},"it":{"nombre_comun":"Prepona a banda azzurra","region":"Dal Messico al Sud America","descripcion":"Farfalla robusta dalle ali nere attraversate da un''ampia fascia blu-verde, mentre il rovescio bruno e mimetico la rende invisibile quando si posa. Ha un volo rapido e potente, ma si avvicina volentieri alla frutta fermentata, dove si lascia osservare da vicino. Porta dimensioni, velocità e riflessi metallici in qualsiasi serra.","vuelo":"Molto rapido e potente","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Prépona à bande bleue","region":"Du Mexique à l''Amérique du Sud","descripcion":"Papillon robuste aux ailes noires traversées d''une large bande bleu-vert, tandis que le revers brun et cryptique le fait disparaître dès qu''il se pose. Son vol est rapide et puissant, mais il vient volontiers sur les fruits fermentés, où l''on peut l''observer de près. Il apporte taille, vitesse et reflets métalliques à toute serre à papillons.","vuelo":"Très rapide et puissant","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"蓝带宝蛱蝶","region":"墨西哥至南美洲","descripcion":"体型健壮，黑色翅面横贯一条宽阔的蓝绿色带纹，翅背面为褐色保护色，停栖时几乎隐身。飞行迅速有力，但很喜欢取食发酵水果，游客可在喂食台近距离观赏。它能为蝴蝶馆带来大体型、速度感和耀眼的金属光泽。","vuelo":"极快而有力","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Catonephele de manchas naranjas', 'Catonephele numilia', 'Nymphalidae', 'México a Sudamérica', 0, 'Especie con marcado dimorfismo: el macho es negro con seis grandes manchas anaranjadas y la hembra, negra con una banda clara amarillenta en el ala anterior. Se alimenta de fruta madura y suele posarse con las alas abiertas en el follaje. Mostrar ambos sexos juntos es una excelente lección visual sobre dimorfismo sexual.', 'catonephele-numilia', '60–75 mm', 'Rápido, a media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Grecian Shoemaker","region":"Mexico to South America","descripcion":"A strikingly dimorphic species: males are black with six bold orange patches, while females are black with a pale yellowish band across the forewing. It feeds on ripe fruit and often perches on foliage with its wings spread. Displaying both sexes side by side makes a vivid, easy-to-grasp lesson in sexual dimorphism.","vuelo":"Fast, at mid-height","disponibilidad":"On request"},"it":{"nombre_comun":"Catonephele a macchie arancioni","region":"Dal Messico al Sud America","descripcion":"Specie dal forte dimorfismo: il maschio è nero con sei grandi macchie arancioni, la femmina è nera con una fascia chiara giallastra sull''ala anteriore. Si nutre di frutta matura e spesso si posa sul fogliame ad ali aperte. Esporre insieme i due sessi offre una lezione immediata sul dimorfismo sessuale.","vuelo":"Rapido, a media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Catonéphèle à taches orange","region":"Du Mexique à l''Amérique du Sud","descripcion":"Espèce au dimorphisme spectaculaire : le mâle est noir avec six grandes taches orange, la femelle noire avec une bande claire jaunâtre sur l''aile antérieure. Elle se nourrit de fruits mûrs et se pose souvent sur le feuillage, ailes ouvertes. Présenter les deux sexes ensemble offre une leçon très parlante sur le dimorphisme sexuel.","vuelo":"Rapide, à mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"橙斑黑蛱蝶","region":"墨西哥至南美洲","descripcion":"雌雄差异极为明显：雄蝶黑色，带六块醒目的橙色大斑；雌蝶黑色，前翅有一条浅黄色斜带。喜食成熟水果，常张开双翅停在叶面上。雌雄同时展出，是讲解性二型现象的生动范例。","vuelo":"迅速，中等高度","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Hoja tigre', 'Consul fabius', 'Nymphalidae', 'México a Sudamérica', 0, 'Por encima luce un patrón atigrado negro, naranja y amarillo que imita a mariposas tóxicas; por debajo, sus alas parecen una hoja seca con nervadura. Acude a la fruta fermentada y, al posarse con las alas cerradas, desaparece entre la vegetación. Ideal para explicar mimetismo y camuflaje en una misma especie.', 'consul-fabius', '70–85 mm', 'Rápido y nervioso', 'Bajo pedido', true, '{"en":{"nombre_comun":"Tiger-striped Leafwing","region":"Mexico to South America","descripcion":"Its upperside wears a black, orange and yellow tiger pattern that mimics distasteful butterflies, while the underside looks just like a dead leaf, complete with a midrib. It comes to fermenting fruit and vanishes into the foliage when it lands with wings closed. A perfect species for explaining both mimicry and camouflage.","vuelo":"Fast and darting","disponibilidad":"On request"},"it":{"nombre_comun":"Foglia tigrata","region":"Dal Messico al Sud America","descripcion":"Sopra sfoggia un disegno tigrato nero, arancio e giallo che imita farfalle tossiche; sotto, le ali sembrano una foglia secca con tanto di nervatura. Si nutre di frutta fermentata e, posata ad ali chiuse, scompare tra la vegetazione. Perfetta per spiegare mimetismo e camuffamento in un''unica specie.","vuelo":"Rapido e scattante","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Feuille tigrée","region":"Du Mexique à l''Amérique du Sud","descripcion":"Le dessus arbore un motif tigré noir, orange et jaune imitant des papillons toxiques, tandis que le revers ressemble à une feuille morte avec sa nervure. Il vient sur les fruits fermentés et disparaît dans le feuillage dès qu''il se pose ailes fermées. Idéal pour illustrer à la fois le mimétisme et le camouflage.","vuelo":"Rapide et vif","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"虎纹枯叶蛱蝶","region":"墨西哥至南美洲","descripcion":"翅正面为黑、橙、黄相间的虎纹，模拟有毒蝴蝶；翅背面则酷似带叶脉的枯叶。喜食发酵水果，合翅停栖时便融入植被之中。一个物种同时展示拟态与伪装，极具教学价值。","vuelo":"迅速而灵活","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Julia', 'Dryas iulia', 'Nymphalidae', 'Sur de EE. UU. a Sudamérica', 0, 'Sus alas alargadas de color naranja intenso, más vivo en los machos, la hacen visible desde cualquier punto del recinto. Es muy activa, recorre las flores de néctar durante todo el día y se adapta con facilidad a la vida en cautiverio. Una especie resistente y colorida, base de casi cualquier exhibición tropical.', 'dryas-iulia', '80–90 mm', 'Rápido y ágil', 'Bajo pedido', true, '{"en":{"nombre_comun":"Julia","region":"Southern USA to South America","descripcion":"Its long, vivid orange wings, brightest in males, stand out from anywhere in the flight house. Highly active, it patrols nectar flowers all day long and settles into captivity with ease. A hardy, colorful species that forms the backbone of almost any tropical butterfly display.","vuelo":"Fast and agile","disponibilidad":"On request"},"it":{"nombre_comun":"Giulia","region":"Dal sud degli USA al Sud America","descripcion":"Le ali allungate di un arancione intenso, più acceso nei maschi, la rendono visibile da ogni punto della serra. È molto attiva, visita i fiori nettariferi per tutto il giorno e si adatta facilmente alla cattività. Specie resistente e colorata, pilastro di quasi ogni esposizione tropicale.","vuelo":"Rapido e agile","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Julia","region":"Du sud des États-Unis à l''Amérique du Sud","descripcion":"Ses ailes allongées d''un orange intense, plus vif chez le mâle, se remarquent de partout dans la serre. Très active, elle butine les fleurs nectarifères toute la journée et s''adapte sans peine à la captivité. Une espèce robuste et colorée, pilier de presque toute exposition tropicale.","vuelo":"Rapide et agile","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"珠袖蝶","region":"美国南部至南美洲","descripcion":"狭长的翅膀呈鲜艳的橙色，雄蝶尤为明亮，在馆内任何角落都十分醒目。它非常活跃，整天在蜜源花丛间穿梭，且容易适应人工饲养环境。这种强健多彩的蝴蝶几乎是每个热带蝴蝶展的基础物种。","vuelo":"迅速灵巧","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Naranja bandeada', 'Dryadula phaetusa', 'Nymphalidae', 'México a Sudamérica', 0, 'Alas anaranjadas cruzadas por franjas negras bien definidas, un diseño limpio y fácil de reconocer. Prefiere volar bajo, cerca de las flores, y se posa con frecuencia a libar néctar a la vista del público. Es una especie tranquila y fotogénica que añade variedad a los tonos naranjas del mariposario.', 'dryadula-phaetusa', '65–80 mm', 'Bajo y pausado', 'Bajo pedido', true, '{"en":{"nombre_comun":"Banded Orange","region":"Mexico to South America","descripcion":"Orange wings crossed by crisp black stripes give it a clean, instantly recognizable pattern. It prefers to fly low near flowers and settles often to sip nectar in full view of visitors. A calm, photogenic species that adds variety to the orange tones of a flight house.","vuelo":"Low and unhurried","disponibilidad":"On request"},"it":{"nombre_comun":"Arancione fasciata","region":"Dal Messico al Sud America","descripcion":"Ali arancioni attraversate da nette strisce nere, un disegno pulito e facile da riconoscere. Preferisce volare basso vicino ai fiori e si posa spesso a bere nettare sotto gli occhi dei visitatori. Specie tranquilla e fotogenica, arricchisce le tonalità arancioni della serra.","vuelo":"Basso e tranquillo","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Orange rayé","region":"Du Mexique à l''Amérique du Sud","descripcion":"Des ailes orange barrées de bandes noires bien nettes lui donnent un motif sobre et facile à reconnaître. Elle vole de préférence bas, près des fleurs, et se pose souvent pour butiner sous les yeux du public. Une espèce calme et photogénique qui diversifie les tons orangés de la serre.","vuelo":"Bas et posé","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"带纹橙蝶","region":"墨西哥至南美洲","descripcion":"橙色翅面上横贯清晰的黑色条纹，图案简洁易认。它喜欢在花丛附近低飞，常停下来吸食花蜜，游客可以清楚观赏。性情温和、上镜，为蝴蝶馆的橙色系增添变化。","vuelo":"低飞，从容","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Mariposa búho púrpura', 'Eryphanis polyxena', 'Nymphalidae', 'México a Sudamérica', 0, 'El macho muestra por encima un intenso violeta iridiscente, mientras que el reverso es pardo, jaspeado y con ocelos, como en las mariposas búho. Es activa al amanecer y al atardecer, y pasa el día posada en la sombra o sobre fruta fermentada. Sorprende al público cuando abre las alas y revela su brillo metálico.', 'eryphanis-polyxena', '90–120 mm', 'Crepuscular, bajo', 'Bajo pedido', true, '{"en":{"nombre_comun":"Purple Mort Bleu","region":"Mexico to South America","descripcion":"Males flash a deep iridescent violet above, while the underside is mottled brown with eyespots, much like an owl butterfly. It is active at dawn and dusk and spends the day resting in shade or feeding on fermenting fruit. Visitors are always surprised when it opens its wings to reveal the metallic sheen.","vuelo":"Crepuscular, low","disponibilidad":"On request"},"it":{"nombre_comun":"Civetta viola","region":"Dal Messico al Sud America","descripcion":"Il maschio mostra sopra un intenso viola iridescente, mentre il rovescio è bruno marmorizzato con ocelli, come nelle farfalle civetta. È attiva all''alba e al tramonto e trascorre il giorno all''ombra o sulla frutta fermentata. Stupisce i visitatori quando apre le ali rivelando i riflessi metallici.","vuelo":"Crepuscolare, basso","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hibou violet","region":"Du Mexique à l''Amérique du Sud","descripcion":"Le mâle affiche un violet irisé profond sur le dessus, tandis que le revers est brun marbré orné d''ocelles, à la manière des papillons hiboux. Actif à l''aube et au crépuscule, il passe la journée à l''ombre ou sur les fruits fermentés. Le public est toujours surpris lorsqu''il ouvre les ailes et révèle son éclat métallique.","vuelo":"Crépusculaire, bas","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"紫闪猫头鹰蝶","region":"墨西哥至南美洲","descripcion":"雄蝶翅正面呈深邃的紫色金属光泽，翅背面为褐色斑驳并带眼斑，与猫头鹰蝶相似。它在黎明和黄昏时最活跃，白天多在阴凉处或发酵水果上停栖。当它展开翅膀露出金属光泽时，总能让游客惊喜。","vuelo":"晨昏活动，低飞","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Isabela', 'Eueides isabella', 'Nymphalidae', 'México a Sudamérica', 0, 'Presenta un diseño atigrado de naranja, negro y amarillo que forma parte de un complejo de mimetismo con otras mariposas de sabor desagradable. Vuela entre las flores de néctar con un aleteo ligero y se posa a menudo, lo que facilita su observación. Aporta color y un buen ejemplo de mimetismo a la exhibición.', 'eueides-isabella', '65–85 mm', 'Ligero, a media altura', 'Bajo pedido', true, '{"en":{"nombre_comun":"Isabella''s Longwing","region":"Mexico to South America","descripcion":"Its orange, black and yellow tiger pattern places it in a mimicry ring shared with other distasteful butterflies. It drifts between nectar flowers with a light wingbeat and perches often, making it easy to observe. It adds warm color to the display and a clear example of mimicry for interpretation.","vuelo":"Light, at mid-height","disponibilidad":"On request"},"it":{"nombre_comun":"Isabella","region":"Dal Messico al Sud America","descripcion":"Il disegno tigrato arancio, nero e giallo la inserisce in un anello mimetico con altre farfalle sgradite ai predatori. Si sposta tra i fiori nettariferi con un battito leggero e si posa spesso, facilitando l''osservazione. Porta colori caldi e un chiaro esempio di mimetismo all''esposizione.","vuelo":"Leggero, a media altezza","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Isabelle","region":"Du Mexique à l''Amérique du Sud","descripcion":"Son motif tigré orange, noir et jaune la rattache à un cercle mimétique partagé avec d''autres papillons au goût désagréable. Elle passe de fleur en fleur d''un battement léger et se pose souvent, ce qui la rend facile à observer. Elle apporte des couleurs chaudes et un bel exemple de mimétisme à l''exposition.","vuelo":"Léger, à mi-hauteur","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"伊莎贝拉长翅蝶","region":"墨西哥至南美洲","descripcion":"橙、黑、黄相间的虎纹使它与其他难吃的蝴蝶组成拟态环。它以轻盈的振翅在蜜源花间穿行，并经常停栖，便于观察。它为展区带来温暖的色彩，也是讲解拟态的绝佳实例。","vuelo":"轻盈，中等高度","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tronadora noche estrellada', 'Hamadryas laodamia', 'Nymphalidae', 'México a Sudamérica', 0, 'La más oscura de las tronadoras: alas casi negras salpicadas de puntos azul brillante, como un cielo nocturno; la hembra añade una banda blanca en el ala anterior. Se posa cabeza abajo en los troncos con las alas abiertas y los machos producen un chasquido audible al volar. Una joya para exhibiciones de ambiente sombreado.', 'hamadryas-laodamia', '65–75 mm', 'Rápido, con chasquidos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Starry Night Cracker","region":"Mexico to South America","descripcion":"The darkest of the crackers: nearly black wings sprinkled with bright blue dots like a night sky, with females adding a white band across the forewing. It rests head-down on trunks with wings spread, and males make an audible clicking sound in flight. A jewel for shaded, forest-style exhibits.","vuelo":"Fast, with clicks","disponibilidad":"On request"},"it":{"nombre_comun":"Cracker notte stellata","region":"Dal Messico al Sud America","descripcion":"La più scura delle cracker: ali quasi nere punteggiate di azzurro brillante come un cielo notturno; la femmina aggiunge una fascia bianca sull''ala anteriore. Si posa a testa in giù sui tronchi ad ali aperte e i maschi producono in volo un clic udibile. Un gioiello per ambientazioni ombreggiate.","vuelo":"Rapido, con scatti sonori","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hamadryas nuit étoilée","region":"Du Mexique à l''Amérique du Sud","descripcion":"La plus sombre des « crackers » : des ailes presque noires parsemées de points bleu vif, comme un ciel nocturne, la femelle ajoutant une bande blanche sur l''aile antérieure. Elle se pose tête en bas sur les troncs, ailes ouvertes, et les mâles émettent un claquement audible en vol. Un joyau pour les décors ombragés.","vuelo":"Rapide, avec claquements","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"星夜蛱蝶","region":"墨西哥至南美洲","descripcion":"袖蛱蝶属中最深色的一种：近乎全黑的翅面点缀着亮蓝色斑点，宛如星空；雌蝶前翅另有一条白色带纹。它常头朝下张翅停在树干上，雄蝶飞行时会发出清晰的咔嗒声。是阴凉林荫展区的一颗明珠。","vuelo":"迅速，伴咔嗒声","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tronadora roja', 'Hamadryas amphinome', 'Nymphalidae', 'México a Sudamérica', 0, 'Por encima es azul oscuro con manchas celestes y una banda blanca en el ala anterior, pero el reverso del ala posterior es de un rojo intenso inconfundible. Descansa cabeza abajo en troncos con las alas abiertas y el macho chasquea en vuelo. El contraste entre su diseño estrellado y el rojo escondido la convierte en favorita del público.', 'hamadryas-amphinome', '70–85 mm', 'Rápido, con chasquidos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Red Cracker","region":"Mexico to South America","descripcion":"Above it is dark blue with pale blue spots and a white band across the forewing, while the hindwing underside is an unmistakable bold red. It rests head-down on trunks with wings open, and males click audibly in flight. The contrast between its starry pattern and the hidden red makes it a visitor favorite.","vuelo":"Fast, with clicks","disponibilidad":"On request"},"it":{"nombre_comun":"Cracker rossa","region":"Dal Messico al Sud America","descripcion":"Sopra è blu scuro con macchie azzurre e una banda bianca sull''ala anteriore, mentre il rovescio dell''ala posteriore è di un rosso intenso inconfondibile. Riposa a testa in giù sui tronchi con le ali aperte e i maschi producono schiocchi udibili in volo. Il contrasto tra il disegno stellato e il rosso nascosto la rende una delle preferite dal pubblico.","vuelo":"Rapido, con scatti sonori","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hamadryas rouge","region":"Du Mexique à l''Amérique du Sud","descripcion":"Le dessus est bleu foncé, ponctué de taches bleu clair et barré d''une bande blanche sur l''aile antérieure, tandis que le revers de l''aile postérieure est d''un rouge vif caractéristique. Il se repose tête en bas sur les troncs, ailes ouvertes, et les mâles émettent des claquements audibles en vol. Le contraste entre son motif étoilé et ce rouge caché en fait un favori du public.","vuelo":"Rapide, avec claquements","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"红腹袖蛱蝶","region":"墨西哥至南美洲","descripcion":"翅膀正面为深蓝色，点缀浅蓝色斑点，前翅有一条白色横带；后翅反面则是醒目的鲜红色。它常头朝下停在树干上并张开翅膀，雄蝶飞行时会发出清晰的咔嗒声。星点花纹与隐藏红色的反差使它深受游客喜爱。","vuelo":"迅速，伴咔嗒声","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tronadora arinome', 'Hamadryas arinome', 'Nymphalidae', 'México a Sudamérica', 0, 'Tronadora de fondo oscuro con reflejos y manchas azul iridiscente que cambian de intensidad según la luz. Como sus parientes, se posa cabeza abajo en los troncos con las alas extendidas y el macho emite chasquidos al volar. Su tono azul profundo complementa muy bien a las tronadoras grises en una misma exhibición.', 'hamadryas-arinome', '70–85 mm', 'Rápido, con chasquidos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Arinome Cracker","region":"Mexico to South America","descripcion":"A dark cracker washed with iridescent blue patches that shift in intensity with the light. Like its relatives, it perches head-down on tree trunks with wings spread, and males click as they fly. Its deep blue tones pair beautifully with the gray crackers in a mixed display.","vuelo":"Fast, with clicks","disponibilidad":"On request"},"it":{"nombre_comun":"Cracker arinome","region":"Dal Messico al Sud America","descripcion":"Una cracker dal fondo scuro con macchie azzurre iridescenti che cambiano intensità con la luce. Come le specie affini, si posa a testa in giù sui tronchi ad ali distese e il maschio schiocca in volo. Le sue tonalità blu profonde si abbinano magnificamente alle cracker grigie.","vuelo":"Rapido, con scatti sonori","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hamadryas arinome","region":"Du Mexique à l''Amérique du Sud","descripcion":"Une « cracker » au fond sombre parsemé de taches bleu irisé dont l''intensité varie avec la lumière. Comme ses proches parentes, elle se pose tête en bas sur les troncs, ailes étalées, et le mâle claque en vol. Ses tons bleu profond s''accordent à merveille avec les espèces grises.","vuelo":"Rapide, avec claquements","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"蓝暗袖蛱蝶","region":"墨西哥至南美洲","descripcion":"翅面底色深暗，带有随光线变化的虹彩蓝斑。与近亲一样，它头朝下展翅停在树干上，雄蝶飞行时会发出咔嗒声。深蓝色调与灰色系的同属种类搭配展示，效果尤佳。","vuelo":"迅速，伴咔嗒声","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tronadora gris', 'Hamadryas februa', 'Nymphalidae', 'México a Sudamérica', 0, 'Gris claro con un intrincado jaspeado blanco, negro y azulado, y el reverso pálido; sobre la corteza resulta casi invisible. Pasa largos ratos cabeza abajo en los troncos con las alas abiertas y acude a la fruta fermentada. Los chasquidos de los machos en vuelo son siempre una sorpresa para los visitantes.', 'hamadryas-februa', '65–80 mm', 'Rápido, con chasquidos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Gray Cracker","region":"Mexico to South America","descripcion":"Pale gray with intricate white, black and bluish marbling and a light underside, it becomes nearly invisible against bark. It spends long stretches head-down on trunks with wings open and comes to fermenting fruit. The clicking of males in flight never fails to surprise visitors.","vuelo":"Fast, with clicks","disponibilidad":"On request"},"it":{"nombre_comun":"Cracker grigia","region":"Dal Messico al Sud America","descripcion":"Grigio chiaro con un intricato marmorizzato bianco, nero e azzurrino e il rovescio pallido: sulla corteccia diventa quasi invisibile. Trascorre a lungo a testa in giù sui tronchi ad ali aperte e visita la frutta fermentata. Gli schiocchi dei maschi in volo sorprendono sempre i visitatori.","vuelo":"Rapido, con scatti sonori","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hamadryas grise","region":"Du Mexique à l''Amérique du Sud","descripcion":"Gris pâle au marbrage complexe blanc, noir et bleuté, avec un revers clair, elle devient presque invisible sur l''écorce. Elle reste longtemps tête en bas sur les troncs, ailes ouvertes, et vient sur les fruits fermentés. Les claquements des mâles en vol surprennent toujours les visiteurs.","vuelo":"Rapide, avec claquements","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"灰袖蛱蝶","region":"墨西哥至南美洲","descripcion":"浅灰色翅面布满白、黑及淡蓝色交织的细纹，翅背面色浅，贴在树皮上几乎无法察觉。它常长时间头朝下张翅停在树干上，也会取食发酵水果。雄蝶飞行时的咔嗒声总让游客感到惊奇。","vuelo":"迅速，伴咔嗒声","disponibilidad":"按需供应"}}'::jsonb)
