insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tronadora variable', 'Hamadryas feronia', 'Nymphalidae', 'México a Sudamérica', 0, 'Mosaico de grises y azules con pequeños ocelos en el ala posterior; su coloración varía bastante entre individuos, de ahí su nombre. Se posa cabeza abajo en los troncos, bien camuflada, y los machos defienden su percha con vuelos cortos y chasquidos audibles. Muy interesante para mostrar variación individual dentro de una especie.', 'hamadryas-feronia', '65–80 mm', 'Rápido, con chasquidos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Variable Cracker","region":"Mexico to South America","descripcion":"A mosaic of grays and blues with small eyespots on the hindwing, its coloring varies noticeably between individuals, hence the name. It perches head-down on trunks, well camouflaged, and males defend their perch with short sallies and audible clicks. Great for showing individual variation within a single species.","vuelo":"Fast, with clicks","disponibilidad":"On request"},"it":{"nombre_comun":"Cracker variabile","region":"Dal Messico al Sud America","descripcion":"Un mosaico di grigi e azzurri con piccoli ocelli sull''ala posteriore; la colorazione varia parecchio da un individuo all''altro, da cui il nome. Si posa a testa in giù sui tronchi ben mimetizzata e i maschi difendono il posatoio con brevi voli e schiocchi udibili. Ideale per mostrare la variabilità individuale.","vuelo":"Rapido, con scatti sonori","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hamadryas variable","region":"Du Mexique à l''Amérique du Sud","descripcion":"Mosaïque de gris et de bleus ornée de petits ocelles sur l''aile postérieure, sa coloration varie nettement d''un individu à l''autre, d''où son nom. Elle se pose tête en bas sur les troncs, bien camouflée, et les mâles défendent leur perchoir par de courts vols et des claquements audibles. Parfaite pour illustrer la variation individuelle.","vuelo":"Rapide, avec claquements","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"多变袖蛱蝶","region":"墨西哥至南美洲","descripcion":"翅面由灰色和蓝色交织成马赛克般的图案，后翅有小眼斑，个体间色彩差异明显，因此得名。它头朝下停在树干上，伪装极佳，雄蝶会以短距离飞行和清晰的咔嗒声守卫栖位。非常适合展示同一物种内的个体差异。","vuelo":"迅速，伴咔嗒声","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tronadora guatemalteca', 'Hamadryas guatemalena', 'Nymphalidae', 'México a Costa Rica', 0, 'Una de las tronadoras más grandes, con alas gris azuladas finamente jaspeadas y una hilera de ocelos en el ala posterior. Típica de bosques secos y abiertos, se asolea cabeza abajo en troncos y postes, y los machos chasquean al perseguir a otros. Su tamaño la hace muy visible en el recinto.', 'hamadryas-guatemalena', '75–90 mm', 'Rápido, con chasquidos', 'Bajo pedido', true, '{"en":{"nombre_comun":"Guatemalan Cracker","region":"Mexico to Costa Rica","descripcion":"One of the larger crackers, with finely mottled blue-gray wings and a row of eyespots on the hindwing. Typical of dry and open forest, it basks head-down on trunks and posts, and males click loudly while chasing rivals. Its size makes it especially easy to spot in a flight house.","vuelo":"Fast, with clicks","disponibilidad":"On request"},"it":{"nombre_comun":"Cracker guatemalteca","region":"Dal Messico alla Costa Rica","descripcion":"Una delle cracker più grandi, con ali grigio-azzurre finemente marmorizzate e una fila di ocelli sull''ala posteriore. Tipica delle foreste secche e aperte, si scalda a testa in giù su tronchi e pali, e i maschi schioccano inseguendo i rivali. Le dimensioni la rendono molto visibile in serra.","vuelo":"Rapido, con scatti sonori","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Hamadryas du Guatemala","region":"Du Mexique au Costa Rica","descripcion":"L''une des plus grandes « crackers », aux ailes gris bleuté finement marbrées et ornées d''une rangée d''ocelles sur l''aile postérieure. Typique des forêts sèches et ouvertes, elle se chauffe tête en bas sur les troncs et les poteaux, et les mâles claquent en poursuivant leurs rivaux. Sa taille la rend très visible en serre.","vuelo":"Rapide, avec claquements","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"危地马拉袖蛱蝶","region":"墨西哥至哥斯达黎加","descripcion":"袖蛱蝶中体型较大的一种，蓝灰色翅面布满细密斑纹，后翅有一列眼斑。常见于干燥开阔的森林，喜欢头朝下在树干或木桩上晒太阳，雄蝶追逐对手时会发出响亮的咔嗒声。较大的体型使它在馆内十分醒目。","vuelo":"迅速，伴咔嗒声","disponibilidad":"按需供应"}}'::jsonb)
on conflict (nombre_cientifico) do update set nombre_comun = excluded.nombre_comun, familia = excluded.familia, region = excluded.region, descripcion = excluded.descripcion, slug = excluded.slug, envergadura = excluded.envergadura, vuelo = excluded.vuelo, traducciones = excluded.traducciones;
insert into especies (nombre_comun, nombre_cientifico, familia, region, precio_unitario, descripcion, slug, envergadura, vuelo, disponibilidad, activo, traducciones) values ('Tigre de manchas crema', 'Tithorea tarricina', 'Nymphalidae', 'México a Sudamérica', 0, 'Alas alargadas con un patrón de franjas negras, naranja y manchas amarillo crema, típico de las mariposas tóxicas que otras especies imitan. Vuela despacio y con confianza entre las flores, sin temor a los depredadores, lo que permite observarla con calma. Excelente para exhibiciones sobre mimetismo y defensas químicas.', 'tithorea-tarricina', '70–80 mm', 'Lento y planeado', 'Bajo pedido', true, '{"en":{"nombre_comun":"Cream-spotted Tigerwing","region":"Mexico to South America","descripcion":"Long wings patterned in black and orange stripes with creamy yellow spots, the classic warning livery of distasteful butterflies that other species copy. It flies slowly and confidently among flowers, unbothered by predators, so visitors can watch it at leisure. Excellent for exhibits on mimicry and chemical defense.","vuelo":"Slow and gliding","disponibilidad":"On request"},"it":{"nombre_comun":"Tigre a macchie crema","region":"Dal Messico al Sud America","descripcion":"Ali allungate con strisce nere e arancioni e macchie giallo crema, la classica livrea d''avvertimento delle farfalle tossiche imitate da altre specie. Vola lentamente e con sicurezza tra i fiori, incurante dei predatori, e si lascia osservare con calma. Ottima per esposizioni su mimetismo e difese chimiche.","vuelo":"Lento e planato","disponibilidad":"Su richiesta"},"fr":{"nombre_comun":"Tigre à taches crème","region":"Du Mexique à l''Amérique du Sud","descripcion":"Des ailes allongées rayées de noir et d''orange et ponctuées de taches jaune crème : la livrée d''avertissement classique des papillons toxiques que d''autres espèces imitent. Elle vole lentement et avec assurance parmi les fleurs, sans craindre les prédateurs, ce qui permet de l''observer tranquillement. Excellente pour les expositions sur le mimétisme et les défenses chimiques.","vuelo":"Lent et plané","disponibilidad":"Sur demande"},"zh":{"nombre_comun":"奶斑虎纹绡蝶","region":"墨西哥至南美洲","descripcion":"狭长的翅膀上有黑橙相间的条纹和奶黄色斑点，这是有毒蝴蝶典型的警戒色，常被其他物种模仿。它在花间缓慢而从容地飞行，不惧天敌，游客可以悠闲观赏。非常适合拟态与化学防御主题的展览。","vuelo":"缓慢滑翔","disponibilidad":"按需供应"}}'::jsonb)
